"""Sprout rewards + Pixelsprout Picks: generated files and page fragments.

Called from site_pages.build_home(), so the daily automation keeps these in
sync with the catalog:

  api/_sprout-games.js   slug -> category map the API uses to validate games
                         (the browser never tells the server a game's category)
  rewards/index.html     Sprout XP, quests, weekly league, privacy controls
  picks/index.html       Pixelsprout Picks (Amazon affiliate recommendations)

Homepage fragments (journey placeholder, favourites shelf, Picks row) are
returned by home_fragments() and inserted by site_pages.render_home().
"""

import json
import os
import re
import urllib.parse

import site_shell as S
from site_shell import esc

PICKS_JSON = os.path.join(S.ROOT, "assets", "picks", "picks.json")
GAME_MAP_JS = os.path.join(S.ROOT, "api", "_sprout-games.js")
SPROUT_CSS = "/assets/sprout/sprout.css?v=20261116a"
ASIN_RE = re.compile(r"^[A-Z0-9]{10}$")
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")
TOOL_GAMES = {"cold-read": "Originals", "gift-file": "Originals"}


# --------------------------------------------------------------------------
# Game map for the API
# --------------------------------------------------------------------------

def game_category(game):
    return S.pretty_genre(S.primary_category(game.get("category") or "")) or "Games"


def write_game_map(catalog, write=True):
    mapping = dict(TOOL_GAMES)
    for g in catalog:
        slug = g.get("slug") or ""
        if re.fullmatch(r"[a-z0-9-]{1,120}", slug):
            mapping[slug] = game_category(g)[:60]
    body = json.dumps(dict(sorted(mapping.items())), ensure_ascii=False, separators=(",", ":"))
    src = (
        "// AUTO-GENERATED by sprout_build.py (via generate-homepage.py). Do not edit.\n"
        "// slug -> category. /api/sprout only accepts games listed here and takes\n"
        "// the category from this map, never from the browser.\n"
        f"export const GAME_CATEGORIES = {body};\n"
    )
    if write:
        old = None
        if os.path.exists(GAME_MAP_JS):
            with open(GAME_MAP_JS, encoding="utf-8") as f:
                old = f.read()
        if old != src:
            with open(GAME_MAP_JS, "w", encoding="utf-8", newline="\n") as f:
                f.write(src)
    return mapping


# --------------------------------------------------------------------------
# Picks
# --------------------------------------------------------------------------

def load_picks():
    try:
        with open(PICKS_JSON, encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def store_of(picks, code=None):
    code = code or picks.get("default_store") or "IN"
    return code, picks["stores"][code]


def search_url(store, query):
    return f"https://{store['domain']}/s?k={urllib.parse.quote_plus(query)}&tag={urllib.parse.quote(store['tag'])}"


def product_url(store, asin):
    return f"https://{store['domain']}/dp/{asin}?tag={urllib.parse.quote(store['tag'])}"


def valid_products(picks):
    """Only products with a real-looking ASIN, known store/category and a
    verification date. Anything else is skipped rather than shown."""
    cats = {c["id"] for c in picks.get("categories", [])}
    out = []
    for p in picks.get("products", []) or []:
        if not isinstance(p, dict):
            continue
        if not (ASIN_RE.match(str(p.get("asin", ""))) and p.get("store") in picks["stores"]
                and p.get("category") in cats and str(p.get("name", "")).strip()
                and str(p.get("description", "")).strip() and DATE_RE.match(str(p.get("verified_on", "")))):
            continue
        img = str(p.get("image") or "")
        if img and not img.startswith("https://m.media-amazon.com/"):
            img = ""
        out.append({**p, "image": img})
    return out


def _paid_link(href, label, cat_id, kind, store_code, query=None, asin=None):
    data = f' data-aff="{kind}" data-aff-cat="{esc(cat_id)}" data-aff-store="{esc(store_code)}"'
    if query:
        data += f' data-aff-q="{esc(query)}"'
    if asin:
        data += f' data-aff-asin="{esc(asin)}"'
    return (f'<a class="pick__cta" href="{esc(href)}" target="_blank" rel="sponsored noopener"{data}>'
            f'{esc(label)}<span class="visually-hidden"> (opens Amazon in a new tab)</span></a>'
            '<span class="pick__paid">(paid link)</span>')


def category_card(picks, cat, heading="h3"):
    code, store = store_of(picks)
    return (
        f'<article class="pick" data-pick="{esc(cat["id"])}">'
        f'<div class="pick__art" aria-hidden="true">{esc(cat.get("art", ""))}</div>'
        '<div class="pick__body">'
        f'<p class="pick__cat">{esc(cat["name"])}</p>'
        f'<{heading} class="pick__name">Browse {esc(cat["name"].lower())}</{heading}>'
        f'<p class="pick__desc">{esc(cat["description"])}</p>'
        f'<div class="pick__foot">{_paid_link(search_url(store, cat["query"]), "View on Amazon", cat["id"], "category", code, query=cat["query"])}</div>'
        "</div></article>"
    )


def product_card(picks, p, heading="h3"):
    store = picks["stores"][p["store"]]
    cats = {c["id"]: c for c in picks["categories"]}
    cat = cats[p["category"]]
    art = (f'<img src="{esc(p["image"])}" alt="{esc(p["name"])}" width="160" height="160" loading="lazy" decoding="async">'
           if p["image"] else f'<span aria-hidden="true">{esc(cat.get("art", ""))}</span>')
    return (
        f'<article class="pick pick--product" data-pick="{esc(cat["id"])}" data-pick-store="{esc(p["store"])}">'
        f'<div class="pick__art">{art}</div>'
        '<div class="pick__body">'
        f'<p class="pick__cat">{esc(cat["name"])}</p>'
        f'<{heading} class="pick__name">{esc(p["name"])}</{heading}>'
        f'<p class="pick__desc">{esc(p["description"])}</p>'
        f'<div class="pick__foot">{_paid_link(product_url(store, p["asin"]), "View on Amazon", cat["id"], "product", p["store"], asin=p["asin"])}</div>'
        "</div></article>"
    )


def disclosure_html(picks):
    return (f'<p class="picks__disclosure"><strong>{esc(picks["disclosure"])}</strong> '
            'Links marked “paid link” go to Amazon. Prices and availability are shown only on Amazon. '
            'Picks are never connected to Sprout XP, quests or rewards.</p>')


def store_toggle(picks):
    btns = "".join(
        f'<button type="button" class="picks__store" data-store="{esc(code)}" aria-pressed="{"true" if code == picks.get("default_store") else "false"}">{esc(s["label"])}</button>'
        for code, s in picks["stores"].items()
    )
    return f'<div class="picks__stores" role="group" aria-label="Amazon store">{btns}</div>'


def home_picks_html(picks):
    if not picks:
        return ""
    cats = {c["id"]: c for c in picks["categories"]}
    chosen = [cats[c] for c in picks.get("home_categories", []) if c in cats][:4]
    if not chosen:
        return ""
    return (
        '<section class="shelf picks" id="pixelsprout-picks" aria-labelledby="picks-title" data-picks="home">'
        '<div class="shelf__head"><h2 class="shelf__title" id="picks-title">Pixelsprout Picks – Gaming Products We Recommend</h2>'
        f'<span class="shelf__spacer"></span><a class="shelf__more" href="/picks/">All picks{S.icon("chevron-right", "i i--sm")}</a></div>'
        f'{disclosure_html(picks)}'
        f'<div class="picks__grid">{"".join(category_card(picks, c) for c in chosen)}</div>'
        "</section>"
    )


# --------------------------------------------------------------------------
# Homepage fragments
# --------------------------------------------------------------------------

def home_fragments():
    journey = (
        '<section class="sj" id="sprout-journey" aria-labelledby="sj-title" hidden>'
        '<div class="sj__head"><h2 class="sj__title" id="sj-title"><span aria-hidden="true">🌱</span> Your Pixelsprout Journey</h2>'
        f'<a class="shelf__more" href="/rewards/">Rewards &amp; league{S.icon("chevron-right", "i i--sm")}</a></div>'
        '<div class="sj__body" data-sj-body></div></section>'
    )
    favourites = S.shelf("Your Favourites", "", section_id="your-favourites", hidden=True,
                         track_id="your-favourites-track")
    return journey, favourites, home_picks_html(load_picks())


SPROUT_HEAD = f'<link rel="stylesheet" href="{SPROUT_CSS}">'


# --------------------------------------------------------------------------
# Pages
# --------------------------------------------------------------------------

def render_rewards_page(total_games=None):
    title = "Sprout XP, Quests and Weekly League | Pixelsprout"
    desc = "Earn Sprout XP by playing free browser games on Pixelsprout. Daily and weekly quests and a weekly league, with no account or sign-up."
    head = S.head(esc(title), esc(desc), canonical=f"{S.DOMAIN}/rewards/",
                  meta_extra='<meta name="robots" content="noindex, follow">', head_extra=SPROUT_HEAD)
    main = f"""<article class="sprout-page" data-sprout-page="rewards">
{S.crumbs([("Home", "/"), ("Rewards", None)])}
<header class="page-head"><p class="eyebrow">No account needed</p><h1 class="page-title"><span aria-hidden="true">🌱</span> Sprout XP &amp; Weekly League</h1>
<p class="sp-lede">Play games, come back on other days and finish quests to grow from Seed to Evergreen. Your progress is tied to this browser only, anonymously.</p></header>
<div class="sp-status" data-sp-status role="status" aria-live="polite">Loading your progress…</div>
<div class="sp-grid">
<section class="sp-card" aria-labelledby="sp-you-title"><h2 class="sp-card__title" id="sp-you-title">Your progress</h2><div data-sp-you></div></section>
<section class="sp-card" aria-labelledby="sp-week-title"><h2 class="sp-card__title" id="sp-week-title">This week</h2><div data-sp-week></div></section>
<section class="sp-card" aria-labelledby="sp-dq-title"><h2 class="sp-card__title" id="sp-dq-title">Daily quests</h2><div data-sp-daily></div></section>
<section class="sp-card" aria-labelledby="sp-wq-title"><h2 class="sp-card__title" id="sp-wq-title">Weekly quests</h2><div data-sp-weekly></div></section>
<section class="sp-card sp-card--wide" aria-labelledby="sp-lb-title"><h2 class="sp-card__title" id="sp-lb-title">Sprout League</h2><div data-sp-league></div></section>
</div>
{S.shelf("Continue playing", "", section_id="continue-playing", hidden=True, track_id="continue-playing-track")}
{S.shelf("Your Favourites", "", section_id="your-favourites", hidden=True, track_id="your-favourites-track")}
<section class="sp-card sp-help" aria-labelledby="sp-how-title">
<h2 class="sp-card__title" id="sp-how-title">How Sprout XP works</h2>
<div class="prose" data-sp-rules>
<ul>
<li>A game session counts once you have actively played it for 60 seconds with the page visible. Opening or refreshing a page earns nothing.</li>
<li>Your first counted session earns <strong>+10 XP</strong>. Coming back and playing on a later day earns <strong>+25 XP</strong> once per day. Playing on 3 different days in the same week earns a <strong>+75 XP</strong> weekly bonus.</li>
<li>Quests reward exploring: new games, new categories and active days. Each quest pays out once per day or week.</li>
<li>Days reset at 00:00 UTC. Weeks and the Sprout League reset every Monday at 00:00 UTC. Lifetime XP and your level never reset.</li>
<li>There is a daily XP limit, and XP is calculated on our server, so repeated reloads or scripts do not help. There are no cash prizes and nothing to buy.</li>
<li>Missing a day never costs you anything. There are no streaks to lose.</li>
</ul>
</div>
</section>
<section class="sp-card sp-help" aria-labelledby="sp-privacy-title" id="privacy-controls">
<h2 class="sp-card__title" id="sp-privacy-title">Your anonymous player ID</h2>
<div class="prose">
<p>Pixelsprout never asks for a name, email or phone number. The first time you use these features, this browser gets a random ID stored in a first-party cookie (<code>ps_pid</code>). We keep your XP, quests, favourites and recently played games against that ID only. We do not use fingerprinting and we never send this ID to Google Analytics or advertisers.</p>
<p>If you clear cookies, use a private window, switch browser or use another device, you will get a new ID and start fresh. We cannot tell that it is you, and we do not try to.</p>
</div>
<div class="sp-actions"><button class="btn btn--ghost" type="button" data-sp-forget>Reset my progress</button><button class="btn btn--ghost" type="button" data-sp-optout>Reset and stop tracking</button><button class="btn btn--ghost" type="button" data-sp-resume hidden>Turn progress back on</button></div>
<p class="sp-note">Read more in our <a href="/privacy.html#player-progress">privacy policy</a>.</p>
</section>
</article>"""
    return S.page(head, main, body_attrs='class="sprout-rewards-page" data-page="rewards"', total_games=total_games)


def render_picks_page(total_games=None):
    picks = load_picks()
    if not picks:
        return None
    title = "Pixelsprout Picks – Gaming Products We Recommend"
    desc = "Gaming mice, headphones, controllers and accessories worth a look for browser gaming. Pixelsprout Picks link to Amazon (paid links)."
    robots = "" if picks.get("indexable") else '<meta name="robots" content="noindex, follow">'
    head = S.head(esc(title + " | Pixelsprout"), esc(desc), canonical=f"{S.DOMAIN}/picks/",
                  meta_extra=robots, head_extra=SPROUT_HEAD)
    products = valid_products(picks)
    product_html = ""
    if products:
        product_html = ('<section class="shelf" aria-labelledby="picks-products-title"><div class="shelf__head">'
                        '<h2 class="shelf__title" id="picks-products-title">Products we recommend</h2></div>'
                        f'<div class="picks__grid">{"".join(product_card(picks, p) for p in products)}</div></section>')
    cats = "".join(category_card(picks, c, heading="h3") for c in picks["categories"])
    main = f"""<article class="picks-page" data-picks="page">
{S.crumbs([("Home", "/"), ("Pixelsprout Picks", None)])}
<header class="page-head"><p class="eyebrow">Gaming gear</p><h1 class="page-title">Pixelsprout Picks – Gaming Products We Recommend</h1>
<p class="sp-lede">Every game on Pixelsprout plays fine with what you already have. If you want to upgrade your setup, these are the kinds of products that genuinely help with browser gaming.</p></header>
{disclosure_html(picks)}
{store_toggle(picks)}
{product_html}
<section class="shelf" aria-labelledby="picks-cats-title"><div class="shelf__head"><h2 class="shelf__title" id="picks-cats-title">Browse by category</h2></div>
<div class="picks__grid">{cats}</div></section>
<section class="sp-card sp-help" aria-labelledby="picks-how-title"><h2 class="sp-card__title" id="picks-how-title">How we pick</h2>
<div class="prose"><ul>
<li>We describe what to look for in each kind of product. We do not show prices, ratings, stock or deals here because they change constantly. Check them on Amazon before you buy.</li>
<li>Pixelsprout does not sell anything and is not offering discounts. Links go straight to Amazon; nothing is hidden or redirected.</li>
<li>Buying something is never needed to play, and clicking a pick never earns Sprout XP, badges or any other reward.</li>
</ul></div></section>
</article>"""
    return S.page(head, main, body_attrs='class="picks-page-body" data-page="picks"', total_games=total_games)


def build_pages(catalog, write=True):
    total = len(catalog)
    write_game_map(catalog, write=write)
    pages = {os.path.join(S.ROOT, "rewards", "index.html"): render_rewards_page(total)}
    picks_page = render_picks_page(total)
    if picks_page:
        pages[os.path.join(S.ROOT, "picks", "index.html")] = picks_page
    if write:
        for path, doc in pages.items():
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8", newline="\n") as f:
                f.write(doc)
    return pages
